//! Bit-exact parity of `fpp::rng` against `fixtures/fpp/rng_golden.json`
//! (generated by `parity/fpp/gen_rng_golden.py` from the reference venv).

use exonit_core::fpp::rng::{tic_seed, tic_seed_key, FppRng};
use serde_json::Value;

fn load() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/fpp/rng_golden.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("read rng_golden.json"))
        .expect("parse rng_golden.json")
}

fn unhex(h: &str) -> f64 {
    let bytes: Vec<u8> = (0..h.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&h[i..i + 2], 16).unwrap())
        .collect();
    f64::from_le_bytes(bytes.try_into().unwrap())
}

fn expect_stream(
    label: &str,
    seed: u32,
    golden: &Value,
    produce: impl Fn(&mut FppRng, usize) -> f64,
) {
    let hexes = golden
        .as_array()
        .unwrap_or_else(|| panic!("{label}: not an array"));
    let mut rng = FppRng::new(seed);
    for (i, h) in hexes.iter().enumerate() {
        let expected = unhex(h.as_str().unwrap());
        let got = produce(&mut rng, i);
        assert_eq!(
            got.to_bits(),
            expected.to_bits(),
            "{label} seed={seed} idx={i}: got {got:e} want {expected:e}"
        );
    }
}

#[test]
fn rng_streams_match_numpy_legacy() {
    let doc = load();
    let rng_doc = &doc["rng"];
    for (seed_str, sec) in rng_doc.as_object().unwrap() {
        let seed: u32 = seed_str.parse().unwrap();
        expect_stream("rand16", seed, &sec["rand16"], |r, _| r.rand());
        // 16 gauss, one rand, 8 gauss — pins the has_gauss cache across
        // the interleaved uniform draw.
        expect_stream(
            "gauss16_rand1_gauss8",
            seed,
            &sec["gauss16_rand1_gauss8"],
            |r, i| {
                if i == 16 {
                    r.rand()
                } else {
                    r.gauss()
                }
            },
        );
        expect_stream("stdexp8", seed, &sec["stdexp8"], |r, _| {
            r.standard_exponential()
        });
        expect_stream("stdgamma_0867_8", seed, &sec["stdgamma_0867_8"], |r, _| {
            r.standard_gamma(0.867)
        });
        expect_stream("stdgamma_3030_8", seed, &sec["stdgamma_3030_8"], |r, _| {
            r.standard_gamma(3.030)
        });
        expect_stream("beta_scipy_16", seed, &sec["beta_scipy_16"], |r, _| {
            r.beta(0.867, 3.030)
        });
        expect_stream(
            "power_scipy_02_8",
            seed,
            &sec["power_scipy_02_8"],
            |r, _| r.power(0.2),
        );
        expect_stream(
            "power_scipy_06_8",
            seed,
            &sec["power_scipy_06_8"],
            |r, _| r.power(0.6),
        );
    }
}

#[test]
fn tic_seeds_match_python_fnv() {
    let doc = load();
    for (stem, entry) in doc["tic_seeds"].as_object().unwrap() {
        let key = entry["key"].as_str().unwrap();
        let seed = entry["seed"].as_u64().unwrap() as u32;
        // Reconstruct (tic_id, period, t0) from the pinned key itself: the
        // test proves Rust formatting reproduces the Python key string AND
        // the FNV hash of it.
        let mut parts = key.splitn(3, ':');
        let tic = parts.next().unwrap();
        let period: f64 = parts.next().unwrap().parse().unwrap();
        let t0: f64 = parts.next().unwrap().parse().unwrap();
        assert_eq!(tic_seed_key(tic, period, t0), key, "{stem}: key formatting");
        assert_eq!(tic_seed(tic, period, t0), seed, "{stem}: seed");
    }
}
